library(rstudioapi)
script_path <- getActiveDocumentContext()$path
setwd(dirname(script_path))
cat("Now working in:", getwd(), "\n")



library(htmlwidgets)
library(plotly)


root <- "../../../../../../analysis/variant_explore/illumina_HC_wgs_XJ4126/06-FST_removed_s16_s17/06-09_poola_AF_perSNP/01_AF_PCA" #fixed
outdir  <- file.path(root, "PCA_plots") #fixed


### need to modify input and output file
# infile  <- file.path(root, "AF_major_chr1.tsv")
# outfile <- file.path(outdir, "PCA_3D_chr1.html")
# 
# infile  <- file.path(root, "AF_major_chr2.tsv")
# outfile <- file.path(outdir, "PCA_3D_chr2.html")

# infile  <- file.path(root, "AF_major_chr3.tsv")
# outfile <- file.path(outdir, "PCA_3D_chr3.html")
# # 
# infile  <- file.path(root, "AF_major_chr4.tsv")
# outfile <- file.path(outdir, "PCA_3D_chr4.html")

# infile  <- file.path(root, "AF_major_chr5.tsv")
# outfile <- file.path(outdir, "PCA_3D_chr5.html")
# 
# infile  <- file.path(root, "AF_major_chrx.tsv")
# outfile <- file.path(outdir, "PCA_3D_chrx.html")

infile  <- file.path(root, "AF_major_genome.tsv")
outfile <- file.path(outdir, "PCA_3D_genome.html")



# extract tag after "AF_major_" and before ".tsv"
tag <- sub("^AF_major_(.+)\\.tsv$", "\\1", basename(infile))

## read data
df <- read.table(infile, header=TRUE, sep="\t", check.names=FALSE)


## drop metadata columns
meta <- c("chr","pos","global_major_allele","allele_states")
df1 <- df[, !(names(df) %in% meta), drop=FALSE]

# transfer AF data to matrix
af <- as.matrix(df1)

# PCA needs samples as rows -> transpose: pools x SNPs
X <- t(af)


# Run PCA (3 components)
pca <- prcomp(X, center=TRUE, scale=TRUE)

### check pca structure
summary(pca)  # check eigenvalue: accounts for variance；Proportion of Variance
pca       # or pca$rotation--check eigenvector: loading/correlation coefficient ; number of PCs == number of parameters/variables
pca$x         # check PC scores: PC for each samples, it is the coordinate of the sample on PCA plots


### check how much variation PC accounts for
pca.var <- pca$sdev^2           # how much variation in the original data each principal component/PC accounts for

pca.var.per <- round(pca.var/sum(pca.var)*100,1) # percentage of variation that each PC accounts for
# same to this code:  summary(pca)$importance["Proportion of Variance", ]

p_2 <- barplot(pca.var.per,main="how much percentage variation each PC accounts for", xlab='principal component',ylab = "Percent variation")
#p_2



## build a data frame with PC scores of samples
scores <- as.data.frame(pca$x[, 1:3])
scores$pool <- rownames(scores)


# create groups based on A,B,C,D... sample ID
scores$group <- sub("[0-9]+$", "", scores$pool)

cols <- c(
  "A" = "#1f77b4",   # blue
  "B" = "#17becf",   # cyan
  "C" = "#2ca02c",   # green
  "D" = "#d62728",   # red
  "E" = "#9467bd",   # purple
  "F" = "#8c564b",   # brown
  "G" = "#e377c2",   # pink
  "H" = "#7f7f7f",   # gray
  "I" = "#bcbd22",   # olive
  "K" = "#ff7f0e",   # orange
  "L" = "#000000",   # black
  "N" = "#00A087"    # teal
)



## to prevent certain labels from overlapping
# set each point's label manually
scores$textpos[scores$pool == "F1"] <- "top center"
scores$textpos[scores$pool == "F2"] <- "left center"
scores$textpos[scores$pool == "A1"] <- "middle right"
scores$textpos[scores$pool == "A2"] <- "top right"
scores$textpos[scores$pool == "B"] <- "left"
scores$textpos[scores$pool == "G1"] <- "right center"
scores$textpos[scores$pool == "G2"] <- "top center"
scores$textpos[scores$pool == "C"] <- "top center"
scores$textpos[scores$pool == "D"] <- "top center"
scores$textpos[scores$pool == "E"] <- "bottom center"
scores$textpos[scores$pool == "F"] <- "top center"
scores$textpos[scores$pool == "H"] <- "top center"
scores$textpos[scores$pool == "I"] <- "top center"
scores$textpos[scores$pool == "N"] <- "bottom"
scores$textpos[scores$pool == "L"] <- "right"
scores$textpos[scores$pool == "K"] <- "top center"



###### 1) 3D interactive plot, save as html: 
