  x = ~PC1, y = ~PC2, z = ~PC3,
  color = ~group, ## color based on group
  colors=cols, # set color by yourself
  text = ~pool,
  type = "scatter3d",
  mode = "markers+text",
  
  marker = list(size = 10), # point size ：  12
