      ),
      zaxis = list(
        title = sprintf("PC3<br>(%.1f%%)", pca.var.per[3]),
        titlefont = list(family = "Arial", size = 16),
        tickfont  = list(family = "Arial", size = 12)
        
      )
      # ,
