library(htmlwidgets)
library(webshot2)

final_figures_outdir= '../../../../../../final_figures/PCA_3D/export_2D_plot'

outfile_html_forwebshot <- file.path(final_figures_outdir, "PCA_3D_genome_tmp_for_webshot.html")
outfile_png  <- file.path(final_figures_outdir, "PCA_3D_genome_high_resolution_webshot.png")


#save interactive plots
saveWidget(pp, outfile_html_forwebshot, selfcontained = TRUE)


#save 2D plots
webshot2::webshot(
  url = outfile_html_forwebshot,
  file = outfile_png,
  vwidth = 2000,
  vheight = 1800,
  zoom = 2,    #  # scale factor; makes output higher resolution
  delay = 2    # wait 2 seconds before screenshot
)

